{
  "story": "Start with fixed Noise and Real examples. Use Next to compare which network changes during each training phase. The Discriminator first learns source labels; then its frozen computation sends Feedback that trains the Generator. The final comparison reveals how competition provides a learning signal.",
  "aha": {
    "stateId": "generator-update",
    "observation": "The Generator learns through a frozen Discriminator; alternating updates train the Discriminator to distinguish Real examples from Generated samples."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "training-rail",
      "kind": "step-rail",
      "presentation": "Use the approved card shell and algorithm stepper composition. Keep story and instructions above the experiment. Show progress only on this rail.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "training-picture",
      "kind": "fixed-picture",
      "presentation": "Keep named regions stationary in the canonical arrangement. Derive geometry from declared regions and links. Highlight active regions without motion. Wrap labels within 640 px.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "active-explanation",
      "kind": "active-callout",
      "presentation": "Anchor beside the active target. Identify where learning occurs without repeating readout values. Reserve readable space in every state.",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "update-comparison",
      "kind": "value-readout",
      "presentation": "Place beneath the picture. Keep both update rows visible for comparison. Display the objective below them and the bound status line last.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "training-step",
      "kind": "index",
      "items": "variant.states",
      "label": "Training step",
      "presentation": "Navigation only; parameter-control budget: zero. Provide Previous and Next. Default index 0; bounds 0–5; increment 1. Retain names when disabled. Support keyboard activation and visible focus. Every state persists until learner action, including the final aha state."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore index 0, initial network states, and the fixed input batches. Provide keyboard activation, an accessible name, and visible focus."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "One alternating GAN training round",
        "regions": [
          {
            "id": "noise",
            "label": "Noise",
            "values": [
              "A fixed batch of random latent inputs for this trace."
            ]
          },
          {
            "id": "real",
            "label": "Real examples",
            "values": [
              "A fixed training batch with known real-source labels."
            ]
          },
          {
            "id": "generator",
            "label": "Generator",
            "phases": [
              "Transforms Noise into Generated samples.",
              "Weights stay fixed during the Discriminator update.",
              "Weights change during the Generator update."
            ]
          },
          {
            "id": "generated",
            "label": "Generated samples",
            "values": [
              "Generator outputs from the fixed Noise batch.",
              "Their generated-source labels are known during Discriminator training.",
              "Recompute these outputs after Generator weights change."
            ]
          },
          {
            "id": "discriminator",
            "label": "Discriminator",
            "values": [
              "Scores Real examples and Generated samples using the same network.",
              "Realness scores are unitless and share a scale; higher means judged more real.",
              "Assume differentiable networks and one Discriminator update followed by one Generator update."
            ]
          },
          {
            "id": "feedback",
            "label": "Feedback",
            "phases": [
              "Discriminator objective: raise real scores and lower generated scores.",
              "Generator objective: raise generated scores using gradients through the frozen Discriminator."
            ]
          }
        ],
        "links": [
          {
            "from": "noise",
            "to": "generator",
            "label": "latent input"
          },
          {
            "from": "generator",
            "to": "generated",
            "label": "generate"
          },
          {
            "from": "real",
            "to": "discriminator",
            "label": "known real source"
          },
          {
            "from": "generated",
            "to": "discriminator",
            "label": "known generated source"
          },
          {
            "from": "discriminator",
            "to": "feedback",
            "label": "scores determine learning signal"
          },
          {
            "from": "feedback",
            "to": "discriminator",
            "label": "Discriminator phase: update weights"
          },
          {
            "from": "feedback",
            "to": "generated",
            "label": "Generator phase: gradient through frozen Discriminator"
          },
          {
            "from": "generated",
            "to": "generator",
            "label": "Generator phase: backpropagate to weights"
          }
        ],
        "states": [
          {
            "id": "start",
            "label": "Start",
            "short": "Two networks",
            "sentence": "The Generator creates candidates; the Discriminator learns to distinguish their source.",
            "why": "Real examples supply training data, while Noise supplies inputs for creating Generated samples.",
            "active": [
              "noise",
              "real",
              "generator",
              "discriminator"
            ],
            "calloutRegion": "generator",
            "readouts": [
              {
                "id": "d-update",
                "label": "Discriminator update",
                "value": "Not performed."
              },
              {
                "id": "g-update",
                "label": "Generator update",
                "value": "Not performed."
              },
              {
                "id": "objective",
                "label": "Current objective",
                "value": "Prepare the two training sources."
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Both networks begin untrained; input batches stay fixed throughout this trace."
              }
            ]
          },
          {
            "id": "generate",
            "label": "Generate",
            "short": "Create candidates",
            "sentence": "The Generator transforms Noise into Generated samples.",
            "why": "Generation is a forward computation; producing samples alone does not update either network.",
            "active": [
              "noise",
              "generator",
              "generated"
            ],
            "calloutRegion": "generated",
            "readouts": [
              {
                "id": "d-update",
                "label": "Discriminator update",
                "value": "Not performed; weights unchanged."
              },
              {
                "id": "g-update",
                "label": "Generator update",
                "value": "Not performed; weights unchanged."
              },
              {
                "id": "objective",
                "label": "Current objective",
                "value": "Create the generated training batch."
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Generated samples are ready for comparison with Real examples."
              }
            ]
          },
          {
            "id": "judge",
            "label": "Judge",
            "short": "Compare sources",
            "sentence": "The same Discriminator scores Real examples and Generated samples.",
            "why": "Known source labels define the Discriminator objective: score real inputs higher and generated inputs lower.",
            "active": [
              "real",
              "generated",
              "discriminator",
              "feedback"
            ],
            "calloutRegion": "discriminator",
            "readouts": [
              {
                "id": "d-update",
                "label": "Discriminator update",
                "value": "Not performed; weights unchanged."
              },
              {
                "id": "g-update",
                "label": "Generator update",
                "value": "Not performed; weights unchanged."
              },
              {
                "id": "objective",
                "label": "Current objective",
                "value": "Raise real scores; lower generated scores."
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Source-label errors now define Feedback for the Discriminator."
              }
            ]
          },
          {
            "id": "discriminator-update",
            "label": "Train Discriminator",
            "short": "Change the critic",
            "sentence": "Feedback updates the Discriminator while the Generator stays fixed.",
            "why": "Generated samples are detached during this update, preventing Discriminator training from changing Generator weights.",
            "active": [
              "discriminator",
              "feedback"
            ],
            "calloutRegion": "discriminator",
            "readouts": [
              {
                "id": "d-update",
                "label": "Discriminator update",
                "value": "Discriminator changed; Generator stayed fixed."
              },
              {
                "id": "g-update",
                "label": "Generator update",
                "value": "Not performed."
              },
              {
                "id": "objective",
                "label": "Current objective",
                "value": "Reduce source-classification error."
              },
              {
                "id": "status",
                "label": "Status",
                "value": "The Discriminator update is complete; now freeze its weights."
              }
            ]
          },
          {
            "id": "generator-feedback",
            "label": "Trace Feedback",
            "short": "Freeze, not disconnect",
            "sentence": "The frozen Discriminator supplies a gradient indicating how Generated samples could receive higher realness scores.",
            "why": "Frozen weights still permit differentiation with respect to inputs, allowing Feedback to reach the Generator.",
            "active": [
              "discriminator",
              "feedback",
              "generated",
              "generator"
            ],
            "calloutRegion": "feedback",
            "readouts": [
              {
                "id": "d-update",
                "label": "Discriminator update",
                "value": "Discriminator changed; Generator stayed fixed."
              },
              {
                "id": "g-update",
                "label": "Generator update",
                "value": "Gradient computed; weights not yet changed."
              },
              {
                "id": "objective",
                "label": "Current objective",
                "value": "Raise scores for Generated samples, rather than classify their true source."
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Feedback passes through the Discriminator without updating its weights."
              }
            ]
          },
          {
            "id": "generator-update",
            "label": "Train Generator",
            "short": "Compare the updates",
            "sentence": "Feedback now updates only the Generator; the Discriminator remains frozen.",
            "why": "The Generator receives a gradient, not a matching target image. One update does not guarantee realistic outputs.",
            "active": [
              "feedback",
              "generated",
              "generator"
            ],
            "calloutRegion": "generator",
            "readouts": [
              {
                "id": "d-update",
                "label": "Discriminator update",
                "value": "Discriminator changed; Generator stayed fixed."
              },
              {
                "id": "g-update",
                "label": "Generator update",
                "value": "Generator changed; Discriminator stayed fixed."
              },
              {
                "id": "objective",
                "label": "Current objective",
                "value": "Make Generated samples score as more real."
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Alternating round complete. Training repeats with newly generated outputs and further Discriminator updates."
              }
            ]
          }
        ]
      }
    ]
  }
}
